CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE role AS ENUM ('ADMIN','IT_OPERATOR','VIEWER','AUDITOR'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE scope_type AS ENUM ('GLOBAL','PROVINCE','SITE'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE asset_group AS ENUM ('OFFICE','NETWORK'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE sync_status AS ENUM ('RUNNING','COMPLETED','PARTIAL','FAILED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS provinces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, code text NOT NULL UNIQUE, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), province_id uuid NOT NULL REFERENCES provinces(id), name text NOT NULL, code text NOT NULL UNIQUE, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sites_province_idx ON sites(province_id);
CREATE TABLE IF NOT EXISTS buildings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid NOT NULL REFERENCES sites(id), name text NOT NULL, code text NOT NULL, is_active boolean NOT NULL DEFAULT true, UNIQUE(site_id,code));
CREATE TABLE IF NOT EXISTS floors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), building_id uuid NOT NULL REFERENCES buildings(id), name text NOT NULL, code text NOT NULL, is_active boolean NOT NULL DEFAULT true, UNIQUE(building_id,code));
CREATE TABLE IF NOT EXISTS rooms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), floor_id uuid NOT NULL REFERENCES floors(id), name text NOT NULL, code text NOT NULL, is_active boolean NOT NULL DEFAULT true, UNIQUE(floor_id,code));
CREATE TABLE IF NOT EXISTS racks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid NOT NULL REFERENCES sites(id), room_id uuid NOT NULL REFERENCES rooms(id), number text NOT NULL, name text NOT NULL, short_code text NOT NULL, description text, is_active boolean NOT NULL DEFAULT true, UNIQUE(site_id,short_code));
CREATE TABLE IF NOT EXISTS owner_companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, code text NOT NULL UNIQUE, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS asset_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "group" asset_group NOT NULL, name text NOT NULL, slug text NOT NULL UNIQUE, code text UNIQUE, is_assignable boolean NOT NULL DEFAULT false, is_active boolean NOT NULL DEFAULT true, form_kind text NOT NULL DEFAULT 'generic');
CREATE TABLE IF NOT EXISTS app_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text NOT NULL UNIQUE, display_name text NOT NULL, email text, password_hash text NOT NULL, role role NOT NULL, is_active boolean NOT NULL DEFAULT true, last_province_id uuid REFERENCES provinces(id), last_site_id uuid REFERENCES sites(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_scopes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, type scope_type NOT NULL, province_id uuid REFERENCES provinces(id), site_id uuid REFERENCES sites(id));
CREATE UNIQUE INDEX IF NOT EXISTS user_scope_uq ON user_scopes(user_id,type,COALESCE(province_id,'00000000-0000-0000-0000-000000000000'),COALESCE(site_id,'00000000-0000-0000-0000-000000000000'));
CREATE TABLE IF NOT EXISTS site_connections (site_id uuid PRIMARY KEY REFERENCES sites(id), encrypted_url text NOT NULL, connect_timeout_ms integer NOT NULL DEFAULT 3000, last_success_at timestamptz, last_failure_at timestamptz, latency_ms integer, last_error_code text);
CREATE TABLE IF NOT EXISTS ad_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), object_guid text NOT NULL UNIQUE, username text NOT NULL, display_name text NOT NULL, email text, department text, title text, company text, distinguished_name text NOT NULL, is_active boolean NOT NULL DEFAULT true, last_synced_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ad_profiles_username_idx ON ad_profiles(username);
CREATE TABLE IF NOT EXISTS ad_ou_mappings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ou_dn text NOT NULL UNIQUE, site_id uuid NOT NULL REFERENCES sites(id), is_active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS ad_sync_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), status sync_status NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, added integer NOT NULL DEFAULT 0, updated integer NOT NULL DEFAULT 0, unchanged integer NOT NULL DEFAULT 0, unmatched integer NOT NULL DEFAULT 0, failed integer NOT NULL DEFAULT 0, details jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS central_audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES app_users(id), action text NOT NULL, entity_type text NOT NULL, entity_id text, site_id uuid REFERENCES sites(id), ip_address text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS central_audit_created_idx ON central_audit_logs(created_at);
